  private def jsonToString(value: JsonValue, indent: Int): String = {
    val nextIndent = if (indent >= 0) indent + 2 else -1
    val spacing = if (indent >= 0) " " * indent else ""
    val newline = if (indent >= 0) "\n" else ""

    value match {
      case JString(s) => s"\"$s\""
      case JNumber(n) => n.toString
      case JBoolean(b) => b.toString
      case JNull => "null"
      case JArray(values) =>
        val items = values.map(v => jsonToString(v, nextIndent)).mkString(", ")
        s"[$items]"
      case JObject(fields) =>
        val items = fields.map { case (k, v) =>
          s"\"$k\": ${jsonToString(v, nextIndent)}"
        }.mkString(", ")
        s"{$items}"
    }
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def navigate(current: JsonValue, remaining: List[String]): Option[JsonValue] = {
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          current match {
            case JObject(fields) =>
              fields.get(head).flatMap(navigate(_, tail))
            case JArray(values) =>
              Try(head.toInt).toOption.flatMap { idx =>
                if (idx >= 0 && idx < values.length) {
                  navigate(values(idx), tail)
                } else None
              }
            case _ => None
          }
      }
    }

    navigate(value, parts).map(tokenize)
  }
}

